# Validation regression tests for ClinicoPath::jjscatterstats
# Generated by /validate-function jjscatterstats depth=exhaustive (2026-11-22)
# Live tests lock in verified behaviour; confirmed open defects carry the correct
# expectation guarded by skip("VAL-jjscatterstats-NN open defect: ...").

# Local helpers (self-contained in-file)
val_render <- function(img) {
  f <- tempfile(fileext = ".png")
  on.exit(unlink(f), add = TRUE)
  ggplot2::set_last_plot(NULL)
  suppressWarnings(suppressMessages(img$saveAs(f)))
  ggplot2::last_plot()
}

val_parse_expr <- function(expr) {
  if (is.null(expr)) return(NULL)
  if (is.expression(expr)) expr <- expr[[1L]]
  if (is.call(expr) && identical(as.character(expr[[1L]]), "atop")) expr <- expr[[2L]]
  if (!is.call(expr) || !identical(as.character(expr[[1L]]), "list")) return(list())
  elems <- as.list(expr)[-1L]
  out <- list()
  for (i in seq_along(elems)) {
    s <- paste(deparse(elems[[i]]), collapse = " ")
    lits <- gsub('^"|"$', "", regmatches(s, gregexpr('"[^"]*"', s))[[1L]])
    if (grepl('log\\[e\\]', s) && grepl('BF\\["01"\\]', s)) {
      out$log_bf01 <- suppressWarnings(as.numeric(tail(lits, 1L)))
    } else if (grepl('italic\\("t"\\)', s) || grepl('italic\\("S"\\)', s)) {
      out$stat_val <- suppressWarnings(as.numeric(tail(lits, 1L)))
      df_m <- regmatches(s, regexpr('\\* "\\(" \\* ([^*]+) \\* "\\)"', s))
      if (length(df_m) == 1L && nzchar(df_m)) {
        out$df <- suppressWarnings(as.numeric(gsub('"', "", trimws(gsub('^\\* "\\(" \\* | \\* "\\)"$', "", df_m)))))
      }
      out$stat_type <- if (grepl('italic\\("t"\\)', s)) "t" else "S"
    } else if (grepl('italic\\(p\\)', s)) {
      out$p_val <- suppressWarnings(as.numeric(tail(lits, 1L)))
    } else if (grepl('widehat\\(', s)) {
      out$est_val <- suppressWarnings(as.numeric(tail(lits, 1L)))
    } else if (grepl('^CI\\[', trimws(s))) {
      if (length(lits) >= 3L) out$ci_low <- suppressWarnings(as.numeric(tail(lits, 1L)))
      if (i < length(elems)) {
        s_next <- paste(deparse(elems[[i + 1L]]), collapse = " ")
        lits_n <- gsub('^"|"$', "", regmatches(s_next, gregexpr('"[^"]*"', s_next))[[1L]])
        if (length(lits_n) >= 1L) out$ci_high <- suppressWarnings(as.numeric(lits_n[1L]))
      }
    } else if (grepl('italic\\("n"\\)', s)) {
      out$n_pairs <- suppressWarnings(as.integer(gsub(",", "", tail(lits, 1L))))
    }
  }
  out
}

val_ggpubr_cor <- function(p) {
  b <- suppressWarnings(ggplot2::ggplot_build(p))
  for (i in seq_along(b$data)) {
    if (all(c("estimate", "p.value", "label") %in% names(b$data[[i]]))) return(b$data[[i]])
  }
  NULL
}

val_tiny <- function() {
  data.frame(
    x = c(1, 2, 2, 4, 5, 6, 8, 10, NA, 3),
    y = c(2, 3, 5, 4, 7, 8, 9, 12, 6, NA),
    col = factor(c("A", "A", "B", "B", "A", "A", "B", "B", "A", "B"))
  )
}

# --- LIVE TESTS (verified PASS claims) ----------------------------------------

test_that("C01: parametric Pearson r, t, df, p, Fisher-z CI and n match closed-form hand oracle", {
  # Oracle: exact hand arithmetic on d_tiny (Sxx=69.5, Syy=79.5, Sxy=71.5, n=8) and stats::cor.test
  skip_if_not_installed("ggstatsplot")
  d <- val_tiny()
  r_true <- 71.5 / sqrt(69.5 * 79.5)
  t_true <- r_true * sqrt(6 / (1 - r_true^2))
  p_true <- 2 * stats::pt(-abs(t_true), df = 6)
  ci_true <- tanh(atanh(r_true) + c(-1, 1) * stats::qnorm(0.975) / sqrt(5))

  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", typestatistics = "parametric", k = 5, conflevel = 0.95
  ))
  s <- val_parse_expr(val_render(res$plot)$labels$subtitle)
  expect_equal(s$est_val,  round(r_true, 5),     tolerance = 5.1e-6)
  expect_equal(s$stat_val, round(t_true, 5),     tolerance = 5.1e-6)
  expect_equal(s$df,       6,                    tolerance = 1e-12)
  expect_equal(s$p_val,    round(p_true, 5),     tolerance = 5.1e-6)
  expect_equal(s$ci_low,   round(ci_true[1], 5), tolerance = 5.1e-6)
  expect_equal(s$ci_high,  round(ci_true[2], 5), tolerance = 5.1e-6)
  expect_equal(s$n_pairs,  8L)
})

test_that("C02: nonparametric Spearman rho, S, t-approx p and Bonett-Wright CI match closed-form oracle on tied data", {
  # Oracle: average-rank Pearson r, S = (n^3-n)(1-rho)/6, Bonett & Wright (2000, DOI:10.1007/BF02294183) CI
  skip_if_not_installed("ggstatsplot")
  d <- val_tiny()
  ok <- is.finite(d$x) & is.finite(d$y)
  x <- d$x[ok]; y <- d$y[ok]; n <- length(x)
  rho_true <- stats::cor(rank(x), rank(y))
  S_true <- (n^3 - n) * (1 - rho_true) / 6
  p_true <- 2 * stats::pt(-abs(rho_true * sqrt((n - 2) / (1 - rho_true^2))), df = n - 2)
  ci_true <- tanh(atanh(rho_true) + c(-1, 1) * stats::qnorm(0.975) * sqrt((1 + (rho_true^2) / 2) / (n - 3)))

  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", typestatistics = "nonparametric", k = 5, conflevel = 0.95
  ))
  s <- val_parse_expr(val_render(res$plot)$labels$subtitle)
  expect_equal(s$est_val,  round(rho_true, 5),   tolerance = 5.1e-6)
  expect_equal(s$stat_val, round(S_true, 5),     tolerance = 5.1e-6)
  expect_equal(s$p_val,    round(p_true, 5),     tolerance = 5.1e-6)
  expect_equal(s$ci_low,   round(ci_true[1], 5), tolerance = 5.1e-6)
  expect_equal(s$ci_high,  round(ci_true[2], 5), tolerance = 5.1e-6)
  expect_equal(s$n_pairs,  8L)
})

