    data = d, dep = "x", group = "y", typestatistics = "robust", k = 5
  ))
  s <- val_parse_expr(val_render(res$plot)$labels$subtitle)
  expect_equal(s$est_val,  round(w$cor, 5),  tolerance = 5.1e-6)
  expect_equal(s$stat_val, round(w$test, 5), tolerance = 5.1e-6)
})

test_that("C04/C05: Bayesian log(BF01) and 95% HDI match independent BayesFactor::correlationBF oracle", {
  # Oracle: BayesFactor::correlationBF(rscale = 0.707) (Ly et al. 2016, DOI:10.1016/j.jmp.2015.06.004)
  skip_if_not_installed("ggstatsplot")
  skip_if_not_installed("BayesFactor")
  set.seed(505)
  d <- data.frame(x = rnorm(60))
  d$y <- 0.52 * d$x + rnorm(60, 0, 0.85)
  bf <- BayesFactor::correlationBF(d$x, d$y, rscale = 0.707)
  log_bf01_true <- -bf@bayesFactor$bf
  set.seed(999)
  dr <- as.numeric(BayesFactor::posterior(bf, iterations = 20000)[, "rho"])
  med_true <- stats::median(dr)

  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", typestatistics = "bayes", k = 5, conflevel = 0.95, seed = 20250101
  ))
  s <- val_parse_expr(val_render(res$plot)$labels$subtitle)
  expect_equal(s$log_bf01, round(log_bf01_true, 5), tolerance = 1e-4)
  expect_equal(s$est_val,  med_true, tolerance = 0.02)

  # Parametric bfmessage caption matches the exact same log(BF01)
  res_p <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", typestatistics = "parametric", bfmessage = TRUE, k = 5
  ))
  cap <- val_parse_expr(val_render(res_p$plot)$labels$caption)
  expect_equal(cap$log_bf01, round(log_bf01_true, 5), tolerance = 1e-4)
})

test_that("C06/C10: grouped mtcars per-panel correlations match subset stats::cor.test", {
  # Oracle: stats::cor.test within each level of factor(mtcars$cyl)
  skip_if_not_installed("ggstatsplot")
  skip_if_not_installed("ggpubr")
  mt <- datasets::mtcars
  mt$cyl_f <- factor(mt$cyl, levels = c(8, 6, 4), labels = c("Eight", "Six", "Four"))
  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = mt, dep = "mpg", group = "hp", grvar = "cyl_f",
    typestatistics = "parametric", k = 5, addGGPubrPlot = TRUE, ggpubrAddCorr = TRUE
  ))
  p2 <- val_render(res$plot2)
  bg2 <- val_ggpubr_cor(val_render(res$ggpubrPlot2))
  for (i in seq_along(levels(mt$cyl_f))) {
    sub_d <- mt[mt$cyl_f == levels(mt$cyl_f)[i], ]
    ct <- stats::cor.test(sub_d$mpg, sub_d$hp)
    s <- val_parse_expr(p2[[i]]$labels$subtitle)
    expect_equal(s$est_val, round(as.numeric(ct$estimate), 5), tolerance = 5.1e-6)
    expect_equal(s$n_pairs, nrow(sub_d))
    expect_equal(bg2$estimate[i], as.numeric(ct$estimate), tolerance = 1e-10)
    expect_equal(bg2$p.value[i],  as.numeric(ct$p.value),  tolerance = 1e-10)
  }
})

test_that("C01/C07/C09: bundled ClinicoPath::jjscatterstats_test cross-panel consistency and 90% CI", {
  # Oracle: stats::cor.test on ClinicoPath::jjscatterstats_test
  skip_if_not_installed("ggstatsplot")
