    data = bt, dep = "protein_expression", group = "mutation_burden", colorvar = "tumor_stage",
    typestatistics = "parametric", conflevel = 0.90, k = 5,
    addGGPubrPlot = TRUE, ggpubrAddCorr = TRUE, ggpubrCorrMethod = "pearson"
  ))
