test_that("C26: metamorphic invariants hold (permutation, affine, sign flip, axis swap, exp for Spearman, CI widening)", {
  # Oracle: mathematical invariances of Pearson, Spearman, and Winsorized correlations
  skip_if_not_installed("ggstatsplot")
  set.seed(303)
  d <- data.frame(x = rnorm(40))
  d$y <- 0.55 * d$x + rnorm(40, 0, 0.8)
  run_sub <- function(dat, ty = "parametric", conf = 0.95, dep = "x", grp = "y") {
    r <- suppressWarnings(do.call(ClinicoPath::jjscatterstats, list(
      data = dat, dep = dep, group = grp, typestatistics = ty, conflevel = conf, k = 5
    )))
    val_parse_expr(val_render(r$plot)$labels$subtitle)
  }
  base_p <- run_sub(d, "parametric")
  expect_equal(run_sub(d[sample(nrow(d)), ], "parametric")$est_val, base_p$est_val, tolerance = 0)
  expect_equal(run_sub(transform(d, x = 3 * x + 100, y = 0.5 * y - 20), "parametric")$est_val, base_p$est_val, tolerance = 5.1e-6)
  neg_p <- run_sub(transform(d, x = -x), "parametric")
  expect_equal(neg_p$est_val, -base_p$est_val, tolerance = 5.1e-6)
  expect_equal(c(neg_p$ci_low, neg_p$ci_high), c(-base_p$ci_high, -base_p$ci_low), tolerance = 5.1e-6)
  expect_equal(run_sub(d, "parametric", dep = "y", grp = "x")$est_val, base_p$est_val, tolerance = 0)

  base_s <- run_sub(d, "nonparametric")
  expect_equal(run_sub(transform(d, x = exp(x), y = exp(y)), "nonparametric")$est_val, base_s$est_val, tolerance = 0)
  ci80 <- run_sub(d, "parametric", conf = 0.80)
  ci99 <- run_sub(d, "parametric", conf = 0.99)
  expect_lt(ci80$ci_high - ci80$ci_low, base_p$ci_high - base_p$ci_low)
  expect_lt(base_p$ci_high - base_p$ci_low, ci99$ci_high - ci99$ci_low)
})

test_that("C16/C17/C18/C19: boundary guards (n=0, Inf/-Inf, 20% missingness, n=9/10/29/30)", {
  # Oracle: specified guard thresholds in R/jjscatterstats.b.R
  skip_if_not_installed("ggstatsplot")
  expect_error(ClinicoPath::jjscatterstats(data = data.frame(x = numeric(0), y = numeric(0)), dep = "x", group = "y"))

  d_inf <- data.frame(x = c(1:10, Inf, -Inf), y = c(2, 4, 5, 7, 8, 10, 11, 13, 15, 17, 1, 2))
  r_inf <- suppressWarnings(ClinicoPath::jjscatterstats(data = d_inf, dep = "x", group = "y", k = 5))
  expect_match(r_inf$warnings$content, "Non-finite values removed", fixed = TRUE)
  expect_equal(val_parse_expr(val_render(r_inf$plot)$labels$subtitle)$n_pairs, 10L)

  set.seed(41)
  d20 <- data.frame(x = rnorm(100), y = rnorm(100)); d20$x[1:20] <- NA
  d19 <- data.frame(x = rnorm(100), y = rnorm(100)); d19$x[1:19] <- NA
  expect_match(ClinicoPath::jjscatterstats(data = d20, dep = "x", group = "y")$warnings$content, "could not be used", fixed = TRUE)
  expect_false(grepl("could not be used", ClinicoPath::jjscatterstats(data = d19, dep = "x", group = "y")$warnings$content %||% "", fixed = TRUE))

  mk <- function(n) { set.seed(n + 100); data.frame(x = rnorm(n), y = rnorm(n)) }
  expect_match(ClinicoPath::jjscatterstats(data = mk(9),  dep = "x", group = "y")$warnings$content, "Very small sample", fixed = TRUE)
  expect_match(ClinicoPath::jjscatterstats(data = mk(10), dep = "x", group = "y")$warnings$content, "Small sample \\(n = 10\\)")
  expect_match(ClinicoPath::jjscatterstats(data = mk(29), dep = "x", group = "y")$warnings$content, "Small sample \\(n = 29\\)")
  expect_false(grepl("small sample", ClinicoPath::jjscatterstats(data = mk(30), dep = "x", group = "y")$warnings$content %||% "", ignore.case = TRUE))
})

test_that("C29/C30: Bayesian seed determinism and R syntax export round-trip", {
  # Oracle: deterministic execution under fixed seed and re-evaluation of asSource()
  skip_if_not_installed("ggstatsplot")
  skip_if_not_installed("BayesFactor")
  set.seed(7)
  d <- data.frame(`Gréade sc` = rnorm(35), `Tumor Size (mm)` = rnorm(35), check.names = FALSE)
  r1 <- suppressWarnings(ClinicoPath::jjscatterstats(data = d, dep = "Gréade sc", group = "Tumor Size (mm)", typestatistics = "bayes", seed = 12345, k = 5))
  r2 <- suppressWarnings(ClinicoPath::jjscatterstats(data = d, dep = "Gréade sc", group = "Tumor Size (mm)", typestatistics = "bayes", seed = 12345, k = 5))
  expect_identical(
    val_parse_expr(val_render(r1$plot)$labels$subtitle)$est_val,
    val_parse_expr(val_render(r2$plot)$labels$subtitle)$est_val
  )

  o <- ClinicoPath:::jjscatterstatsOptions$new(dep = "Gréade sc", group = "Tumor Size (mm)", typestatistics = "nonparametric", k = 4)
  a <- ClinicoPath:::jjscatterstatsClass$new(options = o, data = d)
  a$init(); a$run()
  src <- a$asSource()
  env <- new.env(parent = globalenv()); env$data <- d
  res_ev <- suppressWarnings(eval(parse(text = src), envir = env))
  expect_equal(
    val_parse_expr(val_render(res_ev$plot)$labels$subtitle)$est_val,
    val_parse_expr(val_render(a$results$plot)$labels$subtitle)$est_val,
    tolerance = 0
  )
})

