    addGGPubrPlot = TRUE, ggpubrAddCorr = TRUE
  ))
  p2 <- val_render(res$plot2)
  pg2 <- val_render(res$ggpubrPlot2)
  expect_equal(length(unique(ggplot2::ggplot_build(pg2)$data[[1]]$PANEL)), length(p2$patches$plots) + 1L)
})

test_that("C06: grouped degenerate subgroup emits warning and avoids literal 'NULL == \"NA\"' plotmath", {
  # Oracle: degenerate guard must apply per grvar stratum
  set.seed(1)
  d <- data.frame(
    x = c(rnorm(20), 1, 2, 1:10),
    y = c(rnorm(20), 3, 4, rep(5, 10)),
    g = factor(c(rep("Good", 20), rep("Tiny2", 2), rep("ConstY", 10)))
  )
  res <- suppressWarnings(ClinicoPath::jjscatterstats(data = d, dep = "x", group = "y", grvar = "g"))
  expect_match(res$warnings$content, "Correlation not computed|Small sample", ignore.case = TRUE)
})

test_that("C07/C11: plot3 honors resultssubtitle=FALSE, conflevel on geom_smooth, and clean p-formatting at k=5", {
  # Oracle: option contract for resultssubtitle, conflevel, and k
  set.seed(505)
  d <- data.frame(x = rnorm(60), col = factor(rep(c("A", "B"), 30)))
  d$y <- 0.85 * d$x + rnorm(60, 0, 0.4)
  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", colorvar = "col", resultssubtitle = FALSE, conflevel = 0.80, k = 5
  ))
  p3 <- val_render(res$plot3)
  expect_null(p3$labels$subtitle)
})

test_that("C09/C11/C15: ggpubrPlot honors conflevel, k, constant-y guard, and clearWith titles", {
  # Oracle: ggpubr::ggscatter conf.int.level and stat_cor digits options
  skip_if_not_installed("ggpubr")
  set.seed(505)
  d <- data.frame(x = rnorm(60)); d$y <- 0.52 * d$x + rnorm(60, 0, 0.85)
  res <- suppressWarnings(ClinicoPath::jjscatterstats(
    data = d, dep = "x", group = "y", conflevel = 0.80, k = 4, addGGPubrPlot = TRUE, ggpubrAddCorr = TRUE
  ))
  p <- val_render(res$ggpubrPlot)
  idx <- which(vapply(p$layers, function(l) inherits(l$stat, "StatSmooth"), logical(1)))
  expect_equal(p$layers[[idx[1]]]$stat_params$level, 0.80)
})

test_that("C23: multiplicity warning fires for ggpubrPlot2 even when resultssubtitle=FALSE", {
  # Oracle: unadjusted per-panel tests in ggpubrPlot2 require multiplicity disclosure
  set.seed(505)
